// MARK: - Errors

/// Error enum for Interconnect
public struct InterconnectErrorType: AWSErrorType {
    enum Code: String {
        case accessDeniedException = "AccessDeniedException"
        case interconnectClientException = "InterconnectClientException"
        case interconnectServerException = "InterconnectServerException"
        case interconnectValidationException = "InterconnectValidationException"
        case resourceNotFoundException = "ResourceNotFoundException"
        case serviceQuotaExceededException = "ServiceQuotaExceededException"
        case throttlingException = "ThrottlingException"
    }

    private let error: Code
    public let context: AWSErrorContext?

    /// initialize Interconnect
    public init?(errorCode: String, context: AWSErrorContext) {
        guard let error = Code(rawValue: errorCode) else { return nil }
        self.error = error
        self.context = context
    }

    internal init(_ error: Code) {
        self.error = error
        self.context = nil
    }

    /// return error code string
    public var errorCode: String { self.error.rawValue }

    /// The calling principal is not allowed to access the specified resource, or the resource does not exist.
    public static var accessDeniedException: Self { .init(.accessDeniedException) }
    /// The request was denied due to incorrect client supplied parameters.
    public static var interconnectClientException: Self { .init(.interconnectClientException) }
    /// The request resulted in an exception internal to the service.
    public static var interconnectServerException: Self { .init(.interconnectServerException) }
    /// The input fails to satisfy the constraints specified.
    public static var interconnectValidationException: Self { .init(.interconnectValidationException) }
    /// The request specifies a resource that does not exist on the server.
    public static var resourceNotFoundException: Self { .init(.resourceNotFoundException) }
    /// The requested operation would result in the calling principal exceeding their allotted quota.
    public static var serviceQuotaExceededException: Self { .init(.serviceQuotaExceededException) }
    /// The request was denied due to request throttling.
    public static var throttlingException: Self { .init(.throttlingException) }
}

extension InterconnectErrorType: Equatable {
    public static func == (lhs: InterconnectErrorType, rhs: InterconnectErrorType) -> Bool {
        lhs.error == rhs.error
    }
}

extension InterconnectErrorType: CustomStringConvertible {
    public var description: String {
        return "\(self.error.rawValue): \(self.message ?? "")"
    }
}
